(5715281, 830562, 33672, '<td valign="top">Pretty good ad.   Product is prominently displayed. I would prefer full bottles in the package.</td>', 'Pretty good ad.   Product is prominently displayed. I would prefer full bottles in the package.', '2009-11-05 11:52:41.000000', NULL, 1),
(5715282, 830128, 33672, '<td valign="top">Well done, A bit sharper to highlight the condensation would work better. Comp lends itself perfectly to text placement.</td>', 'Well done, A bit sharper to highlight the condensation would work better. Comp lends itself perfectly to text placement.', '2009-11-05 11:53:50.000000', NULL, 1),
