(5715293, 830512, 33672, '<td valign="top">I love the smokey background. Product is well presented and there''s nice negative space for ad copy., Nice tag line too. If I had one pick, It''d be that there need to be condensation on the bottle to make it more appealing.</td>', 'I love the smokey background. Product is well presented and there''s nice negative space for ad copy., Nice tag line too. If I had one pick, It''d be that there need to be condensation on the bottle to make it more appealing.', '2009-11-05 11:58:06.000000', NULL, 1),
(5715295, 830616, 33672, '<td valign="top">Nice tag line and overall a very nice ad. Comp is perfect for ad copy later and the lighting and product presentation are right on.</td>', 'Nice tag line and overall a very nice ad. Comp is perfect for ad copy later and the lighting and product presentation are right on.', '2009-11-05 11:59:22.000000', NULL, 1),
