INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5806117, 830977, 28427, '<td valign="top">Ah, one of our Belgian beers.  This is probably the only Belgian beer to which they add white candy sugar.<br/>There''s also a reason why the holder and the form of the glass are shaped this way.  It was simply to ease the life of coachmen in the 18th century.  The drivers of mail coaches were not allowed to leave their carriage and horses.  Therefore, Paul Kwak, the brewer of this beer - and also the owner of a café where lots of coachmen stopped by - invented this glass and holder which could easily be hung aside the carriage.<br/>Till there some information for those who might be interested in some history.<br/><br/><i>Message edited by author 2010-01-11 12:43:58.</i></td>', 'Ah, one of our Belgian beers.  This is probably the only Belgian beer to which they add white candy sugar.There''s also a reason why the holder and the form of the glass are shaped this way.  It was simply to ease the life of coachmen in the 18th century.  The drivers of mail coaches were not allowed to leave their carriage and horses.  Therefore, Paul Kwak, the brewer of this beer - and also the owner of a café where lots of coachmen stopped by - invented this glass and holder which could easily be hung aside the carriage.Till there some information for those who might be interested in some history.', '2010-01-11 12:39:51.000000', '2010-01-11 12:43:58.000000', 0),
(5858177, 830962, 114371, '<td valign="top">I like this.  It is different without getting weird.</td>', 'I like this.  It is different without getting weird.', '2010-02-08 01:12:48.000000', NULL, 0),
(5891693, 830209, 66709, '<td valign="top">this is a great shot!!</td>', 'this is a great shot!!', '2010-03-05 16:08:41.000000', NULL, 0),
(5900985, 831037, 108687, '<td valign="top">It is amazing that such a simple set-up produced these results. When you think of what goes into a major production food shoot...  acrylic ice, hand set water droplets, and so on.  Great job!</td>', 'It is amazing that such a simple set-up produced these results. When you think of what goes into a major production food shoot...  acrylic ice, hand set water droplets, and so on.  Great job!', '2010-03-12 07:09:05.000000', NULL, 0),
(5909246, 830665, 35467, '<td valign="top">Very nice processing.</td>', 'Very nice processing.', '2010-03-18 01:06:18.000000', NULL, 0),
(6179452, 831071, 96751, '<td valign="top">It IS a lovely portrait!!</td>', 'It IS a lovely portrait!!', '2010-10-03 17:06:54.000000', NULL, 0),
(6362306, 830508, 103960, '<td valign="top">I have a Nikon D40 and was worried that it was not a sufficient camera to do some quality photos.  I did a search for photos taken with the D40 and came across this one.  I have seen this on an earlier date and love this photo.  Thank you for your detailed description, this is a great shot and gives me faith in my camera!</td>', 'I have a Nikon D40 and was worried that it was not a sufficient camera to do some quality photos.  I did a search for photos taken with the D40 and came across this one.  I have seen this on an earlier date and love this photo.  Thank you for your detailed description, this is a great shot and gives me faith in my camera!', '2011-03-24 10:22:51.000000', NULL, 0),
(6408147, 831071, 91783, '<td valign="top">wow, i didn''t think that this should have gotten 3.0  Its a really nice portrait. just doesn''t meet the challenge.</td>', 'wow, i didn''t think that this should have gotten 3.0  Its a really nice portrait. just doesn''t meet the challenge.', '2011-05-09 01:44:22.000000', NULL, 0);
